"""Local inputs and direct rustc build; all generated bytes stay in build/."""
from __future__ import annotations

import gzip
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import shutil
import struct
import subprocess
import sys
import zipfile

sys.dont_write_bytecode = True
HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[3]
BUILD = HERE / "build"
LX6 = HERE.parent / "lx6-engine-port"
EXE = BUILD / ("lx2.exe" if os.name == "nt" else "lx2")
MODEL_SHA = "223edad95f991ea1ada8ed3d464b21909979f0122aa837fc9e3d7e3541949e01"
FLAGS = ["--edition=2021", "-O", "-D", "warnings", "-C", "debuginfo=0"]
SOURCE_NAMES = ("main.rs", "kernel.rs", "runtime.rs", "wire.rs", "faults.rs",
                "prepare.py", "run.py", "check.py", "SCENARIO.json", "PROVENANCE.json")
REUSED_NAMES = ("engine.rs", "json.rs", "sha256.rs", "export_model.py")


def sha(data):
    return hashlib.sha256(data).hexdigest()


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()


def write_json(path, value):
    path.write_bytes((json.dumps(value, indent=2, sort_keys=True, allow_nan=False) + "\n").encode())


def environment():
    temporary = BUILD / "tmp"
    temporary.mkdir(parents=True, exist_ok=True)
    env = os.environ.copy()
    env.update(TMP=str(temporary), TEMP=str(temporary), TMPDIR=str(temporary),
               PYTHONDONTWRITEBYTECODE="1")
    return env


def cleanup():
    # Verify the absolute deletion target, including every child link, before rmtree.
    if BUILD.exists():
        if BUILD.is_symlink() or BUILD.is_junction() or BUILD.resolve() != HERE / "build":
            raise ValueError("Unexpected build directory")
        if any(p.is_symlink() or p.is_junction() for p in BUILD.rglob("*")):
            raise ValueError("Link in build directory")
        shutil.rmtree(BUILD)


def export_model():
    # Reuse only LX-6's NPY reader. Its old chapter pins and output location are
    # intentionally not invoked; the complete generated model has its own pin.
    spec = importlib.util.spec_from_file_location("lx6_export_readonly", LX6 / "export_model.py")
    reader = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(reader)
    manifest_bytes = (ROOT / "assets/manifest.json").read_bytes()
    manifest = json.loads(manifest_bytes)
    for name, digest in manifest["files"].items():
        if sha((ROOT / name).read_bytes()) != digest:
            raise ValueError("Model asset integrity mismatch")
    census = json.loads((ROOT / "assets/census.json").read_bytes())
    trees = json.loads(gzip.decompress((ROOT / "assets/execution_trees.json.gz").read_bytes()))
    atlas = json.loads((ROOT / "assets/seed_atlas.json").read_bytes())
    if len(trees) != 35 or any(t["seed"] != atlas[i]["word"] for i, t in enumerate(trees)):
        raise ValueError("Execution tree seeds differ")
    meta = canonical(dict(model_id=manifest["model_id"], manifest_sha256=sha(manifest_bytes),
                          census=census["orbits"]))
    with (BUILD / "model.bin").open("wb") as out:
        out.write(b"LX6MOD1\0" + struct.pack("<I", len(meta)) + meta)

        def vector(data):
            out.write(struct.pack("<I", len(data) // 4))
            out.write(data)

        for filename, names in (("model.npz", ("slot_piece", "orbit_id")),
                                ("primitives.npz", ("offsets", "src", "dst"))):
            with zipfile.ZipFile(ROOT / "assets" / filename) as archive:
                for name in names:
                    vector(reader.npy_i32(archive, name))
        out.write(struct.pack("<I", len(trees)))
        for tree in trees:
            for key in ("seed", "relocation", "parent", "move"):
                vector(b"".join(struct.pack("<i", v) for v in tree[key]))
    if sha((BUILD / "model.bin").read_bytes()) != MODEL_SHA:
        raise ValueError("Exported LX-6 model differs")


def pose_fixture():
    # A nonzero, deterministic transfer fixture, NOT poses computed by LX-6.
    # All IDs refer to one of 2,049 table entries; matrices are display data only.
    ids = b"".join(struct.pack("<i", i % 2049) for i in range(177_120))
    matrices = bytearray()
    for i in range(2049):
        diagonal = (-1.0, -1.0, 1.0, 1.0) if i % 2 else (1.0,) * 4
        matrices.extend(struct.pack("<16f", *(diagonal[r] if r == c else 0.0
                                              for r in range(4) for c in range(4))))
    lattice = b"".join(struct.pack("<i", i % 60) for i in range(2049))
    mask = bytes(0xA5 if i % 2 else 0x5A for i in range(22_140))
    data = ids + matrices + lattice + mask
    assert (len(ids), len(matrices), len(lattice), len(mask), len(data)) == (
        708_480, 131_136, 8_196, 22_140, 869_952)
    (BUILD / "pose.bin").write_bytes(data)
    return data


def prepare():
    if BUILD.exists():
        raise ValueError("build/ must be absent before a run")
    env = environment()
    if os.name != "nt":
        import resource
        resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
    export_model()
    pose = pose_fixture()
    sources = {str((HERE / name).relative_to(ROOT)).replace("\\", "/"): sha((HERE / name).read_bytes())
               for name in SOURCE_NAMES}
    sources.update({str((LX6 / name).relative_to(ROOT)).replace("\\", "/"): sha((LX6 / name).read_bytes())
                    for name in REUSED_NAMES})
    identity = dict(sources=sources, flags=FLAGS, model_sha256=MODEL_SHA,
                    pose_sha256=sha(pose), pose_bytes=len(pose))
    candidate_sha = sha(canonical(identity))
    env["LX6_BUILD"] = candidate_sha
    version = subprocess.run(["rustc", "--version", "--verbose"], env=env, check=True,
                             capture_output=True, text=True, timeout=30).stdout.strip()
    flags = FLAGS + (["-C", "link-arg=/Brepro"] if os.name == "nt" else [])
    print("Building LX-2 " + candidate_sha, flush=True)
    subprocess.run(["rustc", "main.rs", *flags, "-o", str(EXE)], cwd=HERE,
                   env=env, check=True, timeout=240)
    subprocess.run([str(EXE), "self-test"], env=env, check=True, timeout=30)
    return dict(candidate_sha256=candidate_sha, identity=identity, rustc=version, flags=flags,
                driver_python=sys.version.split()[0], platform=sys.platform,
                executable_sha256=sha(EXE.read_bytes()))
